'use strict';

// MODULES //

var inherit = require( '@stdlib/utils/inherit' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var Socket = require( './socket/main.js' );
var Message = require( './message' );
var log = require( './custom_log.js' );


// MAIN //

/**
* Shell socket constructor.
*
* @private
* @constructor
* @param {Kernel} kernel - jupyter kernel instance
* @param {Options} options - constructor options
* @param {string} options.ip - client address
* @param {number} options.shell_port - shell port
* @param {string} options.transport - protocol name
* @param {string} options.signature_scheme - signature scheme
* @param {string} options.key - signature key
* @returns {ShellSocket} socket instance
*/
function IOPubSocket( kernel, options ) {
	if ( !( this instanceof IOPubSocket ) ) {
		return new IOPubSocket( kernel, options );
	}

	// Cache a reference to the kernel instance:
	this._kernel = kernel;

	// Call the parent constructor:
	Socket.call(
		this,
		'pub',
		options.ip,
		options.iopub_port,
		options.transport,
		options.signature_scheme,
		options.key
	);

	log( 'iopub_socket.js: Constructing IOPUB at port: ' + String( options.iopub_port ) )

	return this;
}

/*
* Inherit from the `Socket` prototype.
*/
inherit( IOPubSocket, Socket );

/**
* Sets kernel's execution status to 'busy'.
*
* @private
* @name setBusy
* @memberof IOPubSocket.prototype
* @type {Function}
* @param {Message} request - request message
* @returns {void}
*/
setNonEnumerableReadOnly( IOPubSocket.prototype, 'setBusy', function setBusy( request ) {
	var content;

	content = { 'execution_state': 'busy' };

	this.send( 	request.createReply( 'status', content ) );
});

/**
* Sets kernel's execution status to 'idle'.
*
* @private
* @name setIdle
* @memberof IOPubSocket.prototype
* @type {Function}
* @param {Message} request - request message
* @returns {void}
*/
setNonEnumerableReadOnly( IOPubSocket.prototype, 'setIdle', function setIdle( request ) {
	var content;

	content = { 'execution_state': 'idle' };

	this.send( 	request.createReply( 'status', content ) );
});

// TODO: add methods for graceful closing.


// EXPORTS //

module.exports = IOPubSocket;
